      const result = validateMessage({
        type: 'list_sessions',
        limit: 50,
        before: {sessionId: 's1', updatedAt: '2023-01-01T00:00:00Z'},
      });
      expect(result).toEqual({
        valid: true,
        data: {
          type: 'list_sessions',
          limit: 50,
          before: {sessionId: 's1', updatedAt: '2023-01-01T00:00:00Z'},
        },
      });
    });

    it('accepts list_sessions with valid limit and numeric before.updatedAt', () => {
      const result = validateMessage({
        type: 'list_sessions',
        limit: 50,
        before: {sessionId: 's1', updatedAt: 1672531200000},
      });
      expect(result).toEqual({
        valid: true,
        data: {
          type: 'list_sessions',
          limit: 50,
          before: {sessionId: 's1', updatedAt: 1672531200000},
        },
      });
    });

    it('rejects list_sessions with negative limit', () => {
      const result = validateMessage({type: 'list_sessions', limit: -1});
      expect(result).toEqual({valid: false, error: 'limit must be a non-negative integer'});
    });

    it('rejects list_sessions with non-integer limit', () => {
      const result = validateMessage({type: 'list_sessions', limit: 1.5});
      expect(result).toEqual({valid: false, error: 'limit must be a non-negative integer'});
    });

    it('rejects list_sessions with string limit', () => {
      const result = validateMessage({type: 'list_sessions', limit: '10'});
      expect(result).toEqual({valid: false, error: 'limit must be a non-negative integer'});
    });

    it('rejects list_sessions with unparseable before.updatedAt string', () => {
      const result = validateMessage({
        type: 'list_sessions',
        before: {sessionId: 's1', updatedAt: 'not a date'},
      });
      expect(result).toEqual({valid: false, error: 'before.updatedAt must be a valid date string or number'});
    });

    it('rejects list_sessions with missing before.sessionId', () => {
      const result = validateMessage({
        type: 'list_sessions',
        before: {updatedAt: '2023-01-01T00:00:00Z'},
