function validatePingMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.timestamp !== 'number') {
    return {valid: false, error: 'ping must have timestamp number'};
  }

  return {
    valid: true,
    data: {
      type: 'ping',
      timestamp: message.timestamp,
    },
  };
}

function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  let limit: number | undefined;
  if ('limit' in message) {
    if (typeof message.limit !== 'number' || !Number.isInteger(message.limit) || message.limit < 0) {
      return {valid: false, error: 'limit must be a non-negative integer'};
    }
    limit = message.limit;
  }

  let before: {sessionId: string; updatedAt: string | number} | undefined;
  if ('before' in message && message.before !== undefined) {
    if (typeof message.before !== 'object' || message.before === null) {
      return {valid: false, error: 'before must be an object'};
    }
    const b = message.before as Record<string, unknown>;

    if (typeof b.sessionId !== 'string' || b.sessionId.length < 1 || b.sessionId.length > 128) {
      return {valid: false, error: 'before.sessionId must be a string of 1-128 characters'};
    }

    if (typeof b.updatedAt === 'string') {
      if (Number.isNaN(Date.parse(b.updatedAt))) {
        return {valid: false, error: 'before.updatedAt must be a valid date string or number'};
      }
    } else if (typeof b.updatedAt !== 'number') {
      return {valid: false, error: 'before.updatedAt must be a valid date string or number'};
    }

    before = {
      sessionId: b.sessionId,
      updatedAt: b.updatedAt,
    };
  }

  return {
    valid: true,
    data: {
      type: 'list_sessions',
